58:/** Run allowlisted packaged scripts under one private HOME/XDG/Bun/OMP environment. */
59:async function runIsolated(
60:	script: string,
61:	args: readonly string[],
62:	root: string,
63:	executablePath: string,
64:	shell: boolean,
65:): Promise<BundledRunResult> {
66:	if (!isAbsolute(executablePath)) throw new Error(`compiled executable path must be absolute: ${executablePath}`);
67:	const realExecutable = realpathSync(executablePath);
68:	const realRoot = realpathSync(resolve(root));
69:	if (releaseRoot(executablePath) !== realRoot) {
70:		throw new Error(`release root does not match compiled executable: ${realRoot}`);
71:	}
72:	const absoluteScript = resolveBundledScript(script, realRoot);
73:	const identity = resolveOmpIdentity(process.env);
74:	const privateRoot = mkdtempSync(join(runtimeTempRoot(), "omp-kit-runtime-"));
75:	try {
76:		for (const directory of PRIVATE_DIRS) mkdirSync(join(privateRoot, directory));
77:		const child = Bun.spawn(shell ? ["/bin/sh", absoluteScript, ...args] : [realExecutable, absoluteScript, ...args], {
78:			cwd: realRoot,
79:			env: { ...sanitizedEnv(identity, process.env, privateRoot), ...(shell ? {} : { BUN_BE_BUN: "1" }) },
80:			stdout: "pipe",
81:			stderr: "pipe",
82:		});
83:		const [code, stdout, stderr] = await Promise.all([
84:			child.exited,
85:			new Response(child.stdout).text(),
86:			new Response(child.stderr).text(),
87:		]);
88:		return { code, stdout, stderr };
89:	} finally {
90:		rmSync(privateRoot, { recursive: true, force: true });
91:	}
92:}
