72:#[cfg(unix)]
73:fn read_ee_input<R: Read + AsFd>(input: &mut R, budget: Duration) -> Option<Vec<u8>> {
74:    let deadline = Instant::now() + budget;
75:    let mut bytes = Vec::new();
76:    let mut chunk = [0_u8; 8_192];
77:    loop {
78:        let remaining = deadline.saturating_duration_since(Instant::now());
79:        if remaining.is_zero() {
80:            return complete_ee_input(bytes);
81:        }
82:        // A complete event needs no EOF. Drain any bytes already waiting so a
83:        // coalesced trailing payload is still rejected by the object parser.
84:        let ready = is_complete_ee_object(&bytes);
85:        let wait_ms = if ready {
86:            0
87:        } else {
88:            remaining.as_millis().clamp(1, u16::MAX as u128) as u16
89:        };
90:        let mut fds = [PollFd::new(input.as_fd(), PollFlags::POLLIN)];
91:        if poll(&mut fds, wait_ms).ok()? == 0 {
92:            return ready.then_some(bytes);
93:        }
94:        let room = (MAX_STDIN_BYTES + 1 - bytes.len()).min(chunk.len());
95:        let count = input.read(&mut chunk[..room]).ok()?;
96:        if count == 0 {
97:            return Some(bytes);
98:        }
99:        bytes.extend_from_slice(&chunk[..count]);
100:        if bytes.len() > MAX_STDIN_BYTES {
101:            return None;
102:        }
103:    }
104:}
