107:fn collect_imports(tree: &UseTree, prefix: &mut Vec<String>, imports: &mut Vec<(Vec<String>, String)>) {
108:    match tree {
109:        UseTree::Path(path) => {
110:            prefix.push(path.ident.to_string());
111:            collect_imports(&path.tree, prefix, imports);
112:            prefix.pop();
113:        }
114:        UseTree::Name(name) => {
115:            let mut source = prefix.clone();
116:            source.push(name.ident.to_string());
117:            imports.push((source, name.ident.to_string()));
118:        }
119:        UseTree::Rename(rename) => {
120:            let mut source = prefix.clone();
121:            source.push(rename.ident.to_string());
122:            imports.push((source, rename.rename.to_string()));
123:        }
124:        UseTree::Group(group) => {
125:            for item in &group.items {
126:                collect_imports(item, prefix, imports);
127:            }
128:        }
129:        UseTree::Glob(_) => {}
130:    }
131:}
